import { useEffect, useMemo, useRef, useState } from "react";
import { addCalendarDays, type CivilTimeOccurrence } from "@lancerlogin/shared/civil-time";
import { api } from "./dashboard-api";
import { outreachReportingState } from "../../../packages/shared/src/outreach-reporting.ts";
import { OutreachEntryEditDialog } from "./outreach-entry-edit";
import { OutreachClock } from "./outreach-clock";
import { ActivityPublicationControls, OutreachEventScheduleFields, type OutreachActivityPublication, type OutreachEventSchedule, type OutreachPublicationProviders } from "./outreach-activity-publication";
import { useModalFocus } from "./modal-focus";
import { CalendarViewToggle, MonthCalendar, PencilIcon } from "./mobile-calendar";
import { usePath } from "./router";
import { groupOutreachParticipation, loadOutreachPages as readOutreachPages, outreachEntrySource } from "./outreach-participation";

type ActivityMode = "event" | "team" | "task";
type OutreachLabel = { id: string; name: string; archived: boolean; revision: number };
type Team = { id: string; name: string; number: string; program: string; archived: boolean; revision: number; participantCount?: number; countedMinutes?: number };
type Activity = { id: string; mode: ActivityMode; labelIds: string[]; labels: OutreachLabel[]; serviceDate: string; teamId: string | null; title: string; description: string; location: string; impactRelevant: boolean; archived: boolean; revision: number } & OutreachEventSchedule;
type ActivityApi = Omit<Activity, "mode" | "labelIds" | "labels"> & { mode?: ActivityMode; categoryId?: string; labelIds?: string[]; labels?: OutreachLabel[] };
type Member = { id: string; label: string; externalId: string; active: boolean };
type EntryContext = { reportingDays: number; reopenHours: number; revision: number; timeZone: string; today: string };
type Entry = { id: string; memberId: string; activityId: string; revision: number; status: "counted" | "void"; memberName: string; externalId: string; activityTitle: string; categoryName?: string; teamName: string | null; serviceDate: string; timeZone?: string; startLocal: string; endLocal: string; startOccurrence?: CivilTimeOccurrence | null; endOccurrence?: CivilTimeOccurrence | null; durationMinutes: number; createdAt?: string; taskNotes: string; attribution: string; staffReason?: string | null };
type ReopenWindow = { id: string; activityId: string | null; activityTitle: string | null; activityServiceDate: string | null; startsMs: number; expiresMs: number; reason: string; revoked: boolean; revision: number; active: boolean };
type Correction = { id: string; channel: "public" | "discord"; memberName: string; externalId: string; activityId?: string | null; entryId: string | null; claimedServiceDate: string | null; message: string; status: "open" | "resolved"; revision: number; createdAt: string; entryRevision: number | null; entryStatus: "counted" | "void" | null; entryMemberId: string | null; entryActivityId: string | null; entryServiceDate: string | null; startLocal: string | null; endLocal: string | null; startOccurrence: CivilTimeOccurrence | null; endOccurrence: CivilTimeOccurrence | null; taskNotes: string | null; activityTitle: string | null; resolutionAction: string | null; resolutionNote: string | null };
type Publication = OutreachActivityPublication;
type PublicationProviders = OutreachPublicationProviders;
type Page<T> = { items: T[]; nextCursor: string | null };
const loadOutreachPages = <T,>(path: string, signal?: AbortSignal) => readOutreachPages<T>(path, (query, nextSignal) => api<Page<T>>(query, { signal: nextSignal }), signal);
type ActivityView = "calendar" | "table";
const minutes = (value: number) => `${value.toLocaleString()} min (${(value / 60).toFixed(2)} hr)`;
const activityTypes: Array<{ value: ActivityMode; label: string }> = [{ value: "event", label: "Event" }, { value: "team", label: "Team support" }, { value: "task", label: "Other service" }];
const activityTypeLabel = (mode: ActivityMode) => activityTypes.find((item) => item.value === mode)?.label ?? mode;
const normalizeActivity = (item: ActivityApi): Activity => ({ ...item, mode: item.mode ?? (item.categoryId === "team-support" ? "team" : item.categoryId === "other-service" ? "task" : "event"), labelIds: Array.isArray(item.labelIds) ? item.labelIds : [], labels: Array.isArray(item.labels) ? item.labels : [], eventStartLocal: item.eventStartLocal ?? null, eventEndLocal: item.eventEndLocal ?? null, eventStartOccurrence: item.eventStartOccurrence ?? null, eventEndOccurrence: item.eventEndOccurrence ?? null });
const activityPayload = (draft: { mode: ActivityMode; labelIds: string[]; teamId: string; serviceDate: string; title: string; description: string; location: string; impactRelevant: boolean }) => ({ ...draft, teamId: draft.mode === "team" ? draft.teamId : null, archived: false });
export const outreachActivityViewKey = "lancerlogin-outreach-activity-view";
export const outreachActivityVisibilityKey = "lancerlogin-outreach-activity-visibility";
const savedActivityView = (): ActivityView => { try { return window.localStorage.getItem(outreachActivityViewKey) === "table" ? "table" : "calendar"; } catch { return "calendar"; } };
const savedActivityVisibility = (): ActivityMode[] => { try { const raw = window.localStorage.getItem(outreachActivityVisibilityKey); if (raw === null) return ["event"]; const parsed = JSON.parse(raw); return Array.isArray(parsed) ? parsed.filter((item): item is ActivityMode => activityTypes.some((type) => type.value === item)) : ["event"]; } catch { return ["event"]; } };

export function OutreachWorkspace({ activityId, onOpenActivity }: { isAdmin?: boolean; activityId?: string; onOpenActivity?: (id: string) => void } = {}) {
  const { navigate } = usePath();
  const [view, setView] = useState<ActivityView>(savedActivityView); const [logOpen, setLogOpen] = useState(false);
  const chooseView = (next: ActivityView) => { try { window.localStorage.setItem(outreachActivityViewKey, next); } catch { /* Browser storage may be unavailable. */ } setView(next); };
  const [labels, setLabels] = useState<OutreachLabel[]>([]); const [teams, setTeams] = useState<Team[]>([]); const [activities, setActivities] = useState<Activity[]>([]); const [members, setMembers] = useState<Member[]>([]); const [windows, setWindows] = useState<ReopenWindow[]>([]); const [corrections, setCorrections] = useState<Correction[]>([]); const [publications, setPublications] = useState<Publication[]>([]); const [publicationProviders, setPublicationProviders] = useState<PublicationProviders>({ google_calendar: false, discord: false }); const [context, setContext] = useState<EntryContext>(); const [busy, setBusy] = useState(false); const [selectedActivityId, setSelectedActivityId] = useState(""); const [notice, setNotice] = useState<{ tone: "success" | "error"; text: string }>(); const noticeRef = useRef<HTMLParagraphElement>(null);
  async function load() {
    setBusy(true); setNotice(undefined);
    try {
      const [labelPage, teamPage, activityPage, memberPage, windowPage, correctionPage, publicationPage, providers, nextContext] = await Promise.all([
        loadOutreachPages<OutreachLabel>("/admin/hours/labels?archived=all&limit=100"), loadOutreachPages<Team>("/admin/hours/teams?archived=all&limit=100"), loadOutreachPages<ActivityApi>("/admin/hours/activities?archived=all&limit=100"), loadOutreachPages<Member>("/admin/hours/member-choices?active=all&limit=100"), loadOutreachPages<ReopenWindow>("/admin/hours/reopen-windows?limit=100"), loadOutreachPages<Correction>("/admin/hours/corrections?status=all&limit=100"), api<Page<Publication>>("/admin/hours/publications"), api<PublicationProviders>("/admin/hours/publication-providers"), api<EntryContext>("/admin/hours/context"),
      ]);
      setLabels(labelPage); setTeams(teamPage); setActivities(activityPage.map(normalizeActivity)); setMembers([...memberPage].sort((a, b) => a.label.localeCompare(b.label, undefined, { sensitivity: "base" }) || a.externalId.localeCompare(b.externalId))); setWindows(windowPage); setCorrections(correctionPage); setPublications(publicationPage.items); setPublicationProviders(providers); setContext(nextContext);
    } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); throw error; }
    finally { setBusy(false); }
  }
  useEffect(() => { void load().catch(() => undefined); }, []);
  useEffect(() => { if (notice) window.requestAnimationFrame(() => noticeRef.current?.focus()); }, [notice]);
  const activeTeams = teams.filter((item) => !item.archived);
  const openCorrections = corrections.filter((item) => item.status === "open");
  const selectedId = activityId ?? selectedActivityId;
  const selected = activities.find((item) => item.id === selectedId);
  const openActivity = (id: string) => { if (onOpenActivity) onOpenActivity(id); else setSelectedActivityId(id); };
  if (selectedId) return <section className="outreach-workspace meeting-detail-workspace outreach-detail-workspace" aria-labelledby={`outreach-activity-${selectedId}`}><a className="compact-back-link" href="/hours" onClick={event => { if (event.button || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return; event.preventDefault(); setSelectedActivityId(""); navigate("/hours"); }}>← Outreach</a>
    {notice && <p ref={noticeRef} tabIndex={-1} className="ui-status settings-notice" data-tone={notice.tone} role={notice.tone === "error" ? "alert" : "status"}>{notice.text}</p>}
    {busy ? <p className="ui-status" role="status">Loading Outreach activity...</p> : selected && context ? <ActivityDetail key={`${selected.id}:${selected.revision}`} activity={selected} activities={activities} labels={labels.filter((item) => !item.archived)} teams={teams} members={members} windows={windows.filter((item) => item.activityId === selected.id || item.activityId === null)} corrections={corrections.filter((item) => (item.activityId ?? item.entryActivityId) === selected.id)} publication={publications.find((item) => item.activityId === selected.id)} publicationProviders={publicationProviders} context={context} onChanged={load} setNotice={setNotice} /> : <article className="ui-card outreach-stack"><h1 id={`outreach-activity-${selectedId}`}>Activity unavailable</h1><p>Choose another activity or return to Activities.</p></article>}
  </section>;
  return <section className="outreach-workspace operational-browser-page" aria-labelledby="outreach-title" data-walkthrough-page="outreach" data-walkthrough-ready={context && !busy ? "true" : undefined} tabIndex={-1}><div className="page-intro operational-page-intro compact-browser-heading"><h1 id="outreach-title">Outreach</h1><CalendarViewToggle name="outreach-activity-view" label="Activity view" value={view} onChange={chooseView} /></div>{openCorrections.length > 0 && <CorrectionInbox items={openCorrections} onOpenActivity={openActivity} />}{notice && <p ref={noticeRef} tabIndex={-1} className="ui-status settings-notice" data-tone={notice.tone} role={notice.tone === "error" ? "alert" : "status"}>{notice.text}</p>}{busy && <p className="ui-status" role="status">Loading Outreach records...</p>}
    {!busy && context && <ActivityPanel view={view} items={activities} labels={labels} teams={activeTeams} context={context} setSelectedActivityId={openActivity} onChanged={load} setNotice={setNotice} />}
    <details className="outreach-submission-disclosure" open={logOpen} onToggle={event => setLogOpen(event.currentTarget.open)}><summary data-walkthrough="outreach-submission-log">Submission Log</summary>{logOpen && !busy && <SubmissionPanel timeZone={context?.timeZone ?? "UTC"} />}</details>
  </section>;
}


function ActivityPanel({ view, items, labels, teams, context, setSelectedActivityId, onChanged, setNotice }: { view: ActivityView; items: Activity[]; labels: OutreachLabel[]; teams: Team[]; context: EntryContext; setSelectedActivityId: (id: string) => void; onChanged: () => Promise<void>; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [creating, setCreating] = useState(false); const [visibleModes, setVisibleModes] = useState<ActivityMode[]>(savedActivityVisibility); const [calendarOffset, setCalendarOffset] = useState(0); const [search, setSearch] = useState("");
  const activeLabels = labels.filter((item) => !item.archived);
  const visibleItems = useMemo(() => items.filter((item) => visibleModes.includes(item.mode)), [items, visibleModes]);
  const filtered = useMemo(() => { const query = search.trim().toLocaleLowerCase(); const matches = query ? visibleItems.filter((item) => [item.title, item.serviceDate, activityTypeLabel(item.mode), item.description, item.location, item.archived ? "archived" : "active", item.labels.map((label) => label.name).join(" "), item.teamId ? teams.find((team) => team.id === item.teamId)?.name ?? "" : ""].join(" ").toLocaleLowerCase().includes(query)) : visibleItems; return [...matches].sort((left, right) => left.serviceDate.localeCompare(right.serviceDate) || (left.eventStartLocal ?? "").localeCompare(right.eventStartLocal ?? "") || left.title.localeCompare(right.title)); }, [visibleItems, search, teams]);
  function toggleVisibility(mode: ActivityMode, visible: boolean) { const next = visible ? [...visibleModes, mode] : visibleModes.filter((item) => item !== mode); setVisibleModes(next); try { window.localStorage.setItem(outreachActivityVisibilityKey, JSON.stringify(next)); } catch { /* The visibility still changes when browser storage is unavailable. */ } }
  async function created(result: { publicationQueue?: { reason?: string; message?: string } }) { await onChanged(); setNotice(result.publicationQueue?.reason === "queue_failed" ? { tone: "error", text: result.publicationQueue.message ?? "Activity saved, but publication was not queued. Use the publication icons in the activity details." } : { tone: "success", text: "Dated Outreach activity created." }); setCreating(false); }
  const openActivity = (id: string) => setSelectedActivityId(id);
  return <div className="outreach-stack">
    {view === "table" && <section className="meeting-browser-controls compact-table-controls outreach-activity-browser-controls ui-card" aria-label="Outreach activity browser controls" data-walkthrough="outreach-activities"><div className="outreach-activity-picker-group"><label className="meeting-browser-select" data-walkthrough="outreach-staff-exception"><span>Activity</span><select className="ui-control ui-native-select" value="" onChange={(event) => { if (event.target.value) openActivity(event.target.value); }}><option value="">Choose an activity</option>{items.map((item) => <option key={item.id} value={item.id}>{item.serviceDate} - {item.title}</option>)}</select></label><ActivityVisibilityFilter visibleModes={visibleModes} onChange={toggleVisibility} /></div><button className="ui-button ui-button--primary" type="button" aria-haspopup="dialog" data-walkthrough="outreach-submission-sources" onClick={() => setCreating(true)}><span aria-hidden="true">+ </span>Create activity</button></section>}
    {view === "calendar" ? <div data-walkthrough="outreach-activities"><MonthCalendar title="Activity calendar" id="outreach-activity-calendar-title" today={context.today} offset={calendarOffset} onOffset={setCalendarOffset} items={[...visibleItems].sort((a,b) => (a.eventStartLocal ?? "").localeCompare(b.eventStartLocal ?? "") || a.title.localeCompare(b.title))} itemDate={item => item.serviceDate} label="activities" emptyText="No selected activity types scheduled." action={<button className="ui-button ui-button--primary" type="button" aria-haspopup="dialog" data-walkthrough="outreach-submission-sources" onClick={() => setCreating(true)}><span aria-hidden="true">+ </span>Create activity</button>} filter={<ActivityVisibilityFilter visibleModes={visibleModes} onChange={toggleVisibility} />} renderItem={item => <article className="calendar-selected-record" key={item.id}><strong>{item.title}</strong><p>{item.eventStartLocal && item.eventEndLocal ? `${item.eventStartLocal} - ${item.eventEndLocal}` : item.mode === "event" ? "All day" : ""} · {activityTypeLabel(item.mode)}</p>{item.location && <p>{item.location}</p>}<button className="ui-button" type="button" data-walkthrough="outreach-staff-exception" onClick={() => openActivity(item.id)}>Open activity<span className="visually-hidden"> {item.title}</span></button></article>} /></div> : <section className="task-card meeting-directory outreach-activity-directory ui-card" aria-labelledby="outreach-activity-table-title"><div className="table-toolbar"><div className="meeting-directory-heading"><h2 id="outreach-activity-table-title">Activity table</h2><p>{filtered.length} of {visibleItems.length} shown</p></div><label>Search activities<input type="search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Title, date, type, location, labels" /></label></div><div className="responsive-table"><table className="ui-table"><thead><tr><th>Title</th><th>Date</th><th>Type</th><th>Schedule</th><th>Supported team</th><th>Labels</th><th>Status</th></tr></thead><tbody>{filtered.map((item) => { const status = item.archived ? "Archived" : "Active"; const type = activityTypeLabel(item.mode); return <tr className="outreach-activity-table-row" key={item.id}><td className="meeting-title-cell"><a className="outreach-activity-title-link" href={`/hours/activities/${encodeURIComponent(item.id)}`} onClick={event => { if (event.button || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return; event.preventDefault(); openActivity(item.id); }}>{item.title}</a><span className="meeting-mobile-details"><span><small>Date</small>{item.serviceDate}</span><span><small>Type</small>{type}</span><span><small>Status</small>{status}</span></span></td><td>{item.serviceDate}</td><td>{type}</td><td>{item.mode === "event" ? item.eventStartLocal && item.eventEndLocal ? `${item.eventStartLocal} to ${item.eventEndLocal}` : "Not scheduled" : "Not applicable"}</td><td>{item.teamId ? teams.find((team) => team.id === item.teamId)?.name ?? "Supported team" : "None"}</td><td>{item.labels.length ? item.labels.map((label) => label.name).join(", ") : "None"}</td><td>{status}</td></tr>; })}</tbody></table>{filtered.length === 0 && <p className="empty-state">{!visibleModes.length ? "No activity types are selected." : visibleItems.length ? "No activities match this search." : items.length ? "No activities match the visibility filters." : "No Outreach activities yet."}</p>}</div></section>}
    <ActivityCreationDialog open={creating} labels={activeLabels} teams={teams} context={context} onClose={() => setCreating(false)} onCreated={created} />
    </div>;
}

function ActivityVisibilityFilter({ visibleModes, onChange }: { visibleModes: ActivityMode[]; onChange: (mode: ActivityMode, visible: boolean) => void }) {
  const disclosure = useRef<HTMLDetailsElement>(null);
  useEffect(() => {
    const outside = (event: PointerEvent) => { if (event.target instanceof Node && !disclosure.current?.contains(event.target) && disclosure.current) disclosure.current.open = false; };
    const escape = (event: KeyboardEvent) => { if (event.key === "Escape" && disclosure.current?.open) { disclosure.current.open = false; disclosure.current.querySelector("summary")?.focus(); } };
    document.addEventListener("pointerdown", outside); document.addEventListener("keydown", escape);
    return () => { document.removeEventListener("pointerdown", outside); document.removeEventListener("keydown", escape); };
  }, []);
  return <details ref={disclosure} className="outreach-activity-visibility"><summary aria-label={`Filters, ${visibleModes.length} activity types selected`} title="Filter activity types"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5h18M6 12h12M10 19h4" /></svg><small>{visibleModes.length}</small></summary><fieldset className="ui-card"><legend className="visually-hidden">Show activity types</legend>{activityTypes.map((item) => <label className="checkbox-field" key={item.value}><input className="ui-checkbox" type="checkbox" checked={visibleModes.includes(item.value)} onChange={(event) => onChange(item.value, event.target.checked)} /> {item.value === "event" ? "Scheduled events" : item.label}</label>)}</fieldset></details>;
}

function ActivityCreationDialog({ open, labels, teams, context, onClose, onCreated }: { open: boolean; labels: OutreachLabel[]; teams: Team[]; context: EntryContext; onClose: () => void; onCreated: (result: { publicationQueue?: { reason?: string; message?: string } }) => Promise<void> }) {
  const initialDraft = () => ({ mode: "event" as ActivityMode, labelIds: [] as string[], teamId: "", serviceDate: context.today, title: "", description: "", location: "", impactRelevant: true });
  const emptySchedule = (): OutreachEventSchedule => ({ eventStartLocal: null, eventEndLocal: null, eventStartOccurrence: null, eventEndOccurrence: null });
  const dialog = useRef<HTMLElement>(null); const errorAlert = useRef<HTMLParagraphElement>(null); const [draft, setDraft] = useState(initialDraft); const [schedule, setSchedule] = useState<OutreachEventSchedule>(emptySchedule); const [saving, setSaving] = useState(false); const [error, setError] = useState("");
  const reset = () => { setDraft(initialDraft()); setSchedule(emptySchedule()); setError(""); };
  const close = () => { if (saving) return; reset(); onClose(); };
  useModalFocus(dialog, open, saving, close);
  useEffect(() => { if (error) errorAlert.current?.focus(); }, [error]);
  async function create(event: React.FormEvent) { event.preventDefault(); setError(""); setSaving(true); try { const result = await api<{ publicationQueue?: { reason?: string; message?: string } }>("/admin/hours/activities", { method: "POST", body: JSON.stringify({ ...activityPayload(draft), ...(draft.mode === "event" ? schedule : {}) }) }); await onCreated(result); reset(); onClose(); } catch (caught) { setError((caught as Error).message); } finally { setSaving(false); } }
  if (!open) return null;
  return <div className="dialog-backdrop"><section ref={dialog} className="meeting-create-dialog outreach-activity-create-dialog ui-dialog" role="dialog" aria-modal="true" aria-labelledby="outreach-create-activity-title" aria-describedby={`outreach-create-activity-description${error ? " outreach-create-activity-error" : ""}`} tabIndex={-1}><div className="dialog-heading"><div><h2 id="outreach-create-activity-title">Create Outreach activity</h2><p id="outreach-create-activity-description">Add one dated activity without leaving the Outreach workspace.</p></div><button className="ui-button" type="button" aria-label="Close create activity" disabled={saving} onClick={close}>×</button></div><form id="outreach-create-activity-form" className="meeting-create-form outreach-activity-create-form ui-form" aria-busy={saving} onSubmit={create}><label>Activity type<select className="ui-native-select" data-modal-initial-focus required value={draft.mode} onChange={(event) => { const mode = event.target.value as ActivityMode; setDraft({ ...draft, mode, teamId: "" }); if (mode !== "event") setSchedule(emptySchedule()); }}>{activityTypes.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label>{draft.mode === "team" && <label>Supported team<select className="ui-native-select" required value={draft.teamId} onChange={(event) => setDraft({ ...draft, teamId: event.target.value })}><option value="">Choose team</option>{teams.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>}<label>Service date<input type="date" required value={draft.serviceDate} onChange={(event) => setDraft({ ...draft, serviceDate: event.target.value })} /></label><label>Activity title<input required maxLength={150} value={draft.title} onChange={(event) => setDraft({ ...draft, title: event.target.value })} /></label>{draft.mode === "event" && <OutreachEventScheduleFields suppressHelp date={draft.serviceDate} timeZone={context.timeZone} value={schedule} onChange={setSchedule} disabled={saving} />}<label>Description<textarea maxLength={4000} value={draft.description} onChange={(event) => setDraft({ ...draft, description: event.target.value })} /></label><label>Location<input maxLength={300} value={draft.location} onChange={(event) => setDraft({ ...draft, location: event.target.value })} /></label><LabelPicker labels={labels} selected={draft.labelIds} onChange={(labelIds) => setDraft({ ...draft, labelIds })} /><label className="checkbox-field"><input type="checkbox" checked={draft.impactRelevant} onChange={(event) => setDraft({ ...draft, impactRelevant: event.target.checked })} /> Impact relevant</label>{error && <p ref={errorAlert} id="outreach-create-activity-error" className="inline-messages error" role="alert" tabIndex={-1}>{error}</p>}<div className="dialog-actions"><button className="ui-button" type="button" disabled={saving} onClick={close}>Cancel</button><button className="ui-button ui-button--primary" disabled={saving || draft.mode === "team" && !draft.teamId}>{saving ? "Creating..." : "Create activity"}</button></div></form></section></div>;
}

function LabelPicker({ labels, selected, onChange }: { labels: OutreachLabel[]; selected: string[]; onChange: (ids: string[]) => void }) {
  return <fieldset className="outreach-fieldset"><legend>Outreach labels (optional)</legend>{labels.length ? labels.map((label) => <label className="checkbox-field" key={label.id}><input className="ui-checkbox" type="checkbox" checked={selected.includes(label.id)} onChange={(event) => onChange(event.target.checked ? [...selected, label.id] : selected.filter((id) => id !== label.id))} /> {label.name}</label>) : <p className="field-help">No Outreach labels yet. Create one from the Outreach Settings tab or Settings &gt; Outreach, or leave this activity unlabeled.</p>}</fieldset>;
}


function CorrectionInbox({ items, onOpenActivity }: { items: Correction[]; onOpenActivity: (id: string) => void }) {
  const [open, setOpen] = useState(false);
  return <div className="outreach-correction-inbox" data-walkthrough="outreach-corrections"><button className="ui-button" type="button" aria-haspopup="dialog" aria-expanded={open} onClick={() => setOpen((value) => !value)}>Corrections <span className="ui-status" data-tone={items.length ? "warning" : "neutral"}>{items.length}</span></button>{open && <div className="ui-card outreach-correction-inbox-panel" role="dialog" aria-label="Open Outreach corrections"><div className="outreach-row"><strong>Open corrections</strong><button className="ui-button" type="button" onClick={() => setOpen(false)}>Close</button></div>{items.map((item) => { const activityId = item.activityId ?? item.entryActivityId; return <div className="outreach-correction-inbox-item" key={item.id}><strong>{item.memberName}</strong><span>{item.activityTitle ?? "Activity unavailable"}</span><button className="ui-button" type="button" disabled={!activityId} onClick={() => { if (activityId) onOpenActivity(activityId); setOpen(false); }}>Review in activity</button></div>; })}{!items.length && <p>No correction requests need review.</p>}</div>}</div>;
}

function ActivityDetail({ activity, activities, labels, teams, members, windows, corrections, publication, publicationProviders, context, onChanged, setNotice }: { activity: Activity; activities: Activity[]; labels: OutreachLabel[]; teams: Team[]; members: Member[]; windows: ReopenWindow[]; corrections: Correction[]; publication?: Publication; publicationProviders: PublicationProviders; context: EntryContext; onChanged: () => Promise<void>; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [showManual, setShowManual] = useState(false); const [editing, setEditing] = useState(false);
  const open = corrections.filter((item) => item.status === "open"); const resolved = corrections.filter((item) => item.status === "resolved");
  return <article className="outreach-stack" aria-labelledby={`outreach-activity-${activity.id}`}>
    <header className="meeting-detail-heading compact-activity-heading"><div>{activity.archived && <span className="ui-status" data-tone="neutral">Archived</span>}<h1 id={`outreach-activity-${activity.id}`}>{activity.title}</h1><p className="outreach-activity-type">{activityTypeLabel(activity.mode)}</p></div><div className="meeting-detail-actions"><button className="ui-button compact-pencil" type="button" aria-label="Edit activity" aria-haspopup="dialog" onClick={() => setEditing(true)}><PencilIcon /></button></div></header>
    <section className="ui-card outreach-activity-summary" aria-label="Activity summary"><dl>
      <div><dt><ActivityDetailIcon kind="date" />Date</dt><dd>{activity.serviceDate}</dd></div>{activity.mode === "event" && <div><dt><ActivityDetailIcon kind="time" />Time</dt><dd>{activity.eventStartLocal && activity.eventEndLocal ? `${activity.eventStartLocal} to ${activity.eventEndLocal}` : "All day"}</dd></div>}
      <div><dt><ActivityDetailIcon kind="location" />Location</dt><dd>{activity.location || "Not set"}</dd></div><div><dt><ActivityDetailIcon kind="label" />Labels</dt><dd>{activity.labels.map(label => label.name).join(", ") || "None"}</dd></div>
      {activity.mode === "team" && <div><dt>Supported team</dt><dd>{teams.find(team => team.id === activity.teamId)?.name ?? "Unavailable"}</dd></div>}
      <ActivityWindowControls activity={activity} items={windows} context={context} onChanged={onChanged} setNotice={setNotice} />
    </dl><div className="outreach-description-row"><div><strong>Description</strong><p>{activity.description || "No description"}</p></div>{activity.mode === "event" && <ActivityPublicationControls activity={activity} publication={publication} providers={publicationProviders} onChanged={onChanged} setNotice={setNotice} />}</div></section>
    <ActivityParticipation activityId={activity.id} activities={activities} members={members} onChanged={onChanged} setNotice={setNotice} timeZone={context.timeZone} action={!activity.archived && activity.serviceDate <= context.today ? <button className="ui-button ui-button--primary" type="button" aria-expanded={showManual} onClick={() => setShowManual(value => !value)}>Add member participation</button> : undefined}>{showManual && <ManualEntryForm activity={activity} members={members} context={context} onChanged={onChanged} onCancel={() => setShowManual(false)} setNotice={setNotice} />}</ActivityParticipation>
    {(open.length > 0 || resolved.length > 0) && <section className="ui-card outreach-stack" aria-labelledby={`outreach-corrections-${activity.id}`}><h2 id={`outreach-corrections-${activity.id}`}>Correction requests</h2>{open.map((item) => <CorrectionCard key={`${item.id}:${item.revision}`} item={item} activities={activities} members={members} context={context} onChanged={onChanged} setNotice={setNotice} />)}{resolved.length > 0 && <details><summary>Resolved correction history ({resolved.length})</summary><div className="outreach-stack">{resolved.map((item) => <article className="ui-card outreach-row" key={item.id}><div><strong>{item.memberName} - {item.resolutionAction ?? "resolved"}</strong><p>{item.createdAt}</p><small>{item.resolutionNote}</small></div></article>)}</div></details>}</section>}
    {editing && <ActivityEditDialog activity={activity} labels={labels} teams={teams} context={context} onClose={() => setEditing(false)} onChanged={onChanged} setNotice={setNotice} />}

  </article>;
}

function ActivityDetailIcon({ kind }: { kind: "date" | "time" | "location" | "label" }) {
  return <svg className="outreach-detail-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">{kind === "date" ? <><rect x="3" y="4" width="18" height="17" rx="2" /><path d="M6 2v4M18 2v4M3 9h18" /></> : kind === "time" ? <><circle cx="12" cy="12" r="9" /><path d="M12 7v5l3 2" /></> : kind === "location" ? <><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 0 1 16 0Z" /><circle cx="12" cy="10" r="3" /></> : <><path d="M3 3h8l10 10-8 8L3 11V3Z" /><circle cx="7.5" cy="7.5" r="1" /></>}</svg>;
}

function ActivityEditDialog({ activity, labels, teams, context, onClose, onChanged, setNotice }: { activity: Activity; labels: OutreachLabel[]; teams: Team[]; context: EntryContext; onClose: () => void; onChanged: () => Promise<void>; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const dialog = useRef<HTMLElement>(null); const errorAlert = useRef<HTMLParagraphElement>(null);
  const [draft, setDraft] = useState({ mode: activity.mode, teamId: activity.teamId ?? "", title: activity.title, serviceDate: activity.serviceDate, description: activity.description, location: activity.location, impactRelevant: activity.impactRelevant, archived: activity.archived, labelIds: activity.labelIds });
  const [schedule, setSchedule] = useState<OutreachEventSchedule>({ eventStartLocal: activity.eventStartLocal, eventEndLocal: activity.eventEndLocal, eventStartOccurrence: activity.eventStartOccurrence, eventEndOccurrence: activity.eventEndOccurrence });
  const [saving, setSaving] = useState(false); const [error, setError] = useState("");
  const close = () => { if (!saving) onClose(); };
  useModalFocus(dialog, true, saving, close);
  useEffect(() => { if (error) errorAlert.current?.focus(); }, [error]);
  async function save(event: React.FormEvent) {
    event.preventDefault(); setSaving(true); setError("");
    try {
      const result = await api<{ publicationQueue?: { reason?: string; message?: string } }>(`/admin/hours/activities/${encodeURIComponent(activity.id)}`, { method: "PATCH", body: JSON.stringify({ revision: activity.revision, ...draft, teamId: draft.mode === "team" ? draft.teamId : null, ...(draft.mode === "event" ? schedule : { eventStartLocal: null, eventEndLocal: null, eventStartOccurrence: null, eventEndOccurrence: null }) }) });
      await onChanged(); setNotice(result.publicationQueue?.reason === "queue_failed" ? { tone: "error", text: result.publicationQueue.message ?? "Activity saved, but publication was not queued. Use the publication icons in the activity details." } : { tone: "success", text: "Activity details updated." }); onClose();
    } catch (caught) { setError((caught as Error).message); } finally { setSaving(false); }
  }
  return <div className="dialog-backdrop"><section ref={dialog} className="meeting-create-dialog outreach-activity-create-dialog ui-dialog" role="dialog" aria-modal="true" aria-labelledby="outreach-edit-activity-title" tabIndex={-1}>
    <div className="dialog-heading"><div><h2 id="outreach-edit-activity-title">Edit Outreach activity</h2><p>Recorded member times and hours remain unchanged.</p></div><button className="ui-button" type="button" aria-label="Close edit activity" disabled={saving} onClick={close}>×</button></div>
    <form className="meeting-create-form outreach-activity-create-form ui-form" onSubmit={event => void save(event)} aria-busy={saving}>
      <label>Activity type<select className="ui-native-select" required value={draft.mode} disabled={saving} onChange={event => { const mode = event.target.value as ActivityMode; setDraft({ ...draft, mode, teamId: "" }); if (mode !== "event") setSchedule({ eventStartLocal: null, eventEndLocal: null, eventStartOccurrence: null, eventEndOccurrence: null }); }}>{activityTypes.map(type => <option key={type.value} value={type.value}>{type.label}</option>)}</select></label>
      {draft.mode === "team" && <label>Supported team<select className="ui-native-select" required value={draft.teamId} disabled={saving} onChange={event => setDraft({ ...draft, teamId: event.target.value })}><option value="">Choose team</option>{teams.filter(team => !team.archived || team.id === activity.teamId).map(team => <option key={team.id} value={team.id}>{team.name}{team.archived ? " - archived" : ""}</option>)}</select></label>}
      <label>Activity title<input className="ui-control" data-modal-initial-focus required maxLength={150} value={draft.title} disabled={saving} onChange={event => setDraft({ ...draft, title: event.target.value })} /></label>
      <label>Service date<input className="ui-control" type="date" required value={draft.serviceDate} disabled={saving} onChange={event => setDraft({ ...draft, serviceDate: event.target.value })} /></label>
      {draft.mode === "event" && <OutreachEventScheduleFields date={draft.serviceDate} timeZone={context.timeZone} value={schedule} onChange={setSchedule} disabled={saving} />}
      <label>Description<textarea className="ui-control" aria-label="Description" maxLength={4000} value={draft.description} disabled={saving} onChange={event => setDraft({ ...draft, description: event.target.value })} /></label>
      <label>Location<input className="ui-control" maxLength={300} value={draft.location} disabled={saving} onChange={event => setDraft({ ...draft, location: event.target.value })} /></label>
      <LabelPicker labels={labels} selected={draft.labelIds} onChange={labelIds => setDraft({ ...draft, labelIds })} />
      <label className="checkbox-field"><input className="ui-checkbox" type="checkbox" checked={draft.impactRelevant} disabled={saving} onChange={event => setDraft({ ...draft, impactRelevant: event.target.checked })} /> Impact relevant</label>
      <label className="checkbox-field"><input className="ui-checkbox" type="checkbox" checked={draft.archived} disabled={saving} onChange={event => setDraft({ ...draft, archived: event.target.checked })} /> Archived</label>
      {error && <p ref={errorAlert} className="ui-status" data-tone="error" role="alert" tabIndex={-1}>{error}</p>}
      <div className="dialog-actions"><button className="ui-button" type="button" disabled={saving} onClick={close}>Cancel</button><button className="ui-button ui-button--primary" type="submit" disabled={saving}>{saving ? "Saving..." : "Save activity"}</button></div>
    </form>
  </section></div>;
}

function ActivityParticipation({ activityId, timeZone, activities, members, onChanged, setNotice, action, children }: { activityId: string; timeZone: string; activities: Activity[]; members: Member[]; onChanged: () => Promise<void>; setNotice: (notice: { tone: "success" | "error"; text: string }) => void; action?: React.ReactNode; children?: React.ReactNode }) {
  const [entries, setEntries] = useState<Entry[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [expanded, setExpanded] = useState<string[]>([]);
  useEffect(() => {
    const controller = new AbortController(); setLoading(true); setEntries([]); setError(""); setExpanded([]);
    void loadOutreachPages<Entry>(`/admin/hours/entries?activityId=${encodeURIComponent(activityId)}&status=all&limit=100`, controller.signal).then((items) => { if (!controller.signal.aborted) setEntries(items); }).catch((caught) => { if (!controller.signal.aborted) setError((caught as Error).message); }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [activityId]);
  const [edit, setEdit] = useState<{ entry: Entry; deleting: boolean }>();
  const groups = useMemo(() => groupOutreachParticipation(entries), [entries]);
  const countedMinutes = groups.reduce((total, member) => total + member.minutes, 0);
  return <section className="attendance-card ui-card outreach-stack outreach-participation-card" aria-labelledby="outreach-participation-title"><div className="panel-heading"><h2 id="outreach-participation-title">Logged participation</h2>{!loading && !error && <span className="progress-count">{(countedMinutes / 60).toFixed(2)} hours total</span>}</div>{action && <div className="outreach-participation-action">{action}</div>}{children}
    {loading ? <p className="ui-status" role="status">Loading all participation for this activity...</p> : error ? <p className="ui-status" data-tone="error" role="alert">{error} Totals are unavailable until every page loads. Refresh this page to retry.</p> : !groups.length ? <p className="empty-state">No participation submissions for this activity yet.</p> : <div className="responsive-table"><table className="ui-table outreach-participation-table" aria-label="Activity participation"><thead><tr><th>Name</th><th>Hours</th><th><span className="visually-hidden">Details</span></th></tr></thead><tbody>{groups.map((member) => <ParticipationMember key={member.memberId} member={member} timeZone={timeZone} onEdit={(entry, deleting) => setEdit({ entry, deleting })} expanded={expanded.includes(member.memberId)} onToggle={() => setExpanded((current) => current.includes(member.memberId) ? current.filter((id) => id !== member.memberId) : [...current, member.memberId])} />)}</tbody></table></div>}
    {edit && <OutreachEntryEditDialog entry={edit.entry} deleting={edit.deleting} activities={activities} members={members} timeZone={timeZone} onClose={() => setEdit(undefined)} onChanged={onChanged} setNotice={setNotice} />}
  </section>;
}

function ParticipationMember({ member, timeZone, expanded, onToggle, onEdit }: { member: ReturnType<typeof groupOutreachParticipation<Entry>>[number]; timeZone: string; expanded: boolean; onToggle: () => void; onEdit: (entry: Entry, deleting: boolean) => void }) {
  const detailId = `outreach-participation-${member.memberId}`;
  return <><tr><th scope="row">{member.name}</th><td>{(member.minutes / 60).toFixed(2)}</td><td><button className="ui-button outreach-details-toggle" type="button" aria-expanded={expanded} aria-controls={detailId} onClick={onToggle}><span className="outreach-details-toggle-sizing" aria-hidden="true">Hide details</span><span>{expanded ? "Hide details" : "Details"}<span className="visually-hidden"> for {member.name}</span></span></button></td></tr>{expanded && <tr id={detailId}><td colSpan={3}><div className="outreach-stack outreach-participation-submissions">{member.entries.map(entry => <article className="outreach-entry-row" key={entry.id} aria-label={`Participation on ${entry.serviceDate}, ${entry.startLocal} to ${entry.endLocal}`} data-entry-id={entry.id}>
    <div><strong>{entry.serviceDate} - {entry.startLocal} to {entry.endLocal}</strong><small>{outreachEntrySource(entry.attribution)} - Revision {entry.revision} - {entry.timeZone ?? timeZone}{entry.startOccurrence ? ` - start: ${entry.startOccurrence}` : ""}{entry.endOccurrence ? ` - end: ${entry.endOccurrence}` : ""}</small>{entry.taskNotes && <p><strong>Notes:</strong> {entry.taskNotes}</p>}{entry.staffReason && <p><strong>Staff reason:</strong> {entry.staffReason}</p>}</div>
    <div><strong>{(entry.durationMinutes / 60).toFixed(2)} hours</strong>{entry.status === "void" && <small>Deleted - excluded from totals</small>}</div>
    <div className="module-actions"><button className="ui-button" type="button" disabled={entry.status !== "counted"} onClick={() => onEdit(entry, false)}>Edit<span className="visually-hidden"> participation for {member.name} on {entry.serviceDate}, {entry.startLocal} to {entry.endLocal}</span></button><button className="ui-button ui-button--danger" type="button" disabled={entry.status !== "counted"} onClick={() => onEdit(entry, true)}>Delete<span className="visually-hidden"> participation for {member.name} on {entry.serviceDate}, {entry.startLocal} to {entry.endLocal}</span></button></div>
  </article>)}</div></td></tr>}</>;
}

function ActivityWindowControls({ activity, items, context, onChanged, setNotice }: { activity: Activity; items: ReopenWindow[]; context: EntryContext; onChanged: () => Promise<void>; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [now, setNow] = useState(Date.now); const [saving, setSaving] = useState(false);
  useEffect(() => { const timer = window.setInterval(() => setNow(Date.now()), 30000); return () => window.clearInterval(timer); }, []);
  const reporting = outreachReportingState(activity, context, items, now);
  async function reopen() {
    setSaving(true);
    try { await api("/admin/hours/reopen-windows", { method: "POST", body: JSON.stringify({ activityId: activity.id, hours: 24, reason: "Reporting reopened for 24 hours", settingsRevision: context.revision }) }); await onChanged(); setNotice({ tone: "success", text: "Reporting reopened for 24 hours." }); }
    catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setSaving(false); }
  }
  return <div className="outreach-reporting-summary"><dt>Reporting</dt><dd><span>{reporting.open ? `Closes ${new Intl.DateTimeFormat(undefined, { timeZone: context.timeZone, dateStyle: "medium", timeStyle: "short" }).format(reporting.closesMs)}` : "Report closed"}</span>{reporting.canReopen && <button className="ui-button" type="button" disabled={saving} onClick={() => void reopen()}>Reopen for 24 hours</button>}</dd></div>;
}

function ManualEntryForm({ activity, members, context, onChanged, onCancel, setNotice }: { activity: Activity; members: Member[]; context: EntryContext; onChanged: () => Promise<void>; onCancel: () => void; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [memberId, setMemberId] = useState(members[0]?.id ?? ""); const [startLocal, setStartLocal] = useState("09:00"); const [endLocal, setEndLocal] = useState("10:00"); const [startOccurrence, setStartOccurrence] = useState<CivilTimeOccurrence>(); const [endOccurrence, setEndOccurrence] = useState<CivilTimeOccurrence>(); const [taskNotes, setTaskNotes] = useState(""); const [staffReason, setStaffReason] = useState(""); const [saving, setSaving] = useState(false); const [pending, setPending] = useState<Record<string, unknown>>();
  const body = useMemo(() => ({ memberId, activityId: activity.id, serviceDate: activity.serviceDate, startLocal, endLocal, ...(startOccurrence ? { startOccurrence } : {}), ...(endOccurrence ? { endOccurrence } : {}), taskNotes, staffReason, expectedTimeZone: context.timeZone }), [memberId, activity.id, activity.serviceDate, startLocal, endLocal, startOccurrence, endOccurrence, taskNotes, staffReason, context.timeZone]);
  async function save(event?: React.FormEvent, exact?: Record<string, unknown>) { event?.preventDefault(); const submission = exact ?? { ...body, idempotencyKey: crypto.randomUUID() }; setPending(submission); setSaving(true); try { await api("/admin/hours/entries", { method: "POST", body: JSON.stringify(submission) }); setPending(undefined); await onChanged(); setNotice({ tone: "success", text: "Manual Outreach participation counted and attributed to Staff." }); } catch (error) { setNotice({ tone: "error", text: `${(error as Error).message} The same submission can be retried without double counting.` }); } finally { setSaving(false); } }
  return <form className="ui-card ui-form outreach-stack" onSubmit={(event) => void save(event)}><div><p className="kicker">Staff exception</p><h3>Add member participation</h3><p><strong>{activity.title}</strong> on {activity.serviceDate}. Start and end use {context.timeZone}. The server rejects overlaps and records whole minutes.</p></div><label>Member<select className="ui-native-select" required value={memberId} onChange={(event) => setMemberId(event.target.value)}>{members.map((item) => <option key={item.id} value={item.id}>{item.label} ({item.externalId}){item.active ? "" : " - inactive"}</option>)}</select></label><div className="outreach-time-grid"><OutreachClock label="Start time" date={activity.serviceDate} time={startLocal} zone={context.timeZone} occurrence={startOccurrence} onTime={setStartLocal} onOccurrence={setStartOccurrence} disabled={saving} /><OutreachClock label="End time" date={activity.serviceDate} time={endLocal} zone={context.timeZone} occurrence={endOccurrence} onTime={setEndLocal} onOccurrence={setEndOccurrence} disabled={saving} /></div><label>Staff reason<textarea required maxLength={4000} value={staffReason} onChange={(event) => setStaffReason(event.target.value)} /></label><label>Task notes (optional)<textarea maxLength={4000} value={taskNotes} onChange={(event) => setTaskNotes(event.target.value)} /></label><div className="module-actions"><button className="ui-button ui-button--primary" disabled={saving || !memberId || !staffReason.trim()}>Save manual participation</button>{pending && <button className="ui-button" type="button" disabled={saving} onClick={() => void save(undefined, pending)}>Retry exact submission</button>}<button className="ui-button" type="button" disabled={saving} onClick={onCancel}>Cancel</button></div></form>;
}

function SubmissionPanel({ timeZone }: { timeZone: string }) {
  const [page, setPage] = useState<Page<Entry>>(); const [cursor, setCursor] = useState<string | null>(null); const [previous, setPrevious] = useState<Array<string | null>>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  const log = useRef<HTMLElement>(null); const pagination = useRef<HTMLElement>(null);
  useEffect(() => {
    if (!pagination.current || !log.current) return;
    const reserveSpace = () => { if (pagination.current && log.current) log.current.style.setProperty("--outreach-pagination-height", `${pagination.current.getBoundingClientRect().height}px`); };
    const observer = new ResizeObserver(reserveSpace); observer.observe(pagination.current); reserveSpace();
    return () => observer.disconnect();
  }, []);
  useEffect(() => {
    const controller = new AbortController(); setLoading(true); setError(""); setPage(undefined);
    void api<Page<Entry>>(`/admin/hours/entries?order=logged-desc&limit=25${cursor ? `&after=${encodeURIComponent(cursor)}` : ""}`, { signal: controller.signal }).then(next => { if (!controller.signal.aborted) setPage(next); }).catch(error => { if (!controller.signal.aborted) setError((error as Error).message); }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [cursor]);
  return <section ref={log} className="outreach-stack outreach-submission-log" aria-labelledby="outreach-submission-log-title"><div><h2 id="outreach-submission-log-title">Submission Log</h2><p>Newest logged entries first. Staff-added participation retains its source and reason.</p></div>
    {loading ? <p className="ui-status" role="status">Loading submissions...</p> : error ? <p className="ui-status" data-tone="error" role="alert">{error}</p> : page?.items.map(item => <article className="ui-card outreach-row" key={item.id}><div><strong>{item.memberName} - {item.activityTitle}</strong><p>{item.serviceDate}, {item.startLocal} to {item.endLocal} - {minutes(item.durationMinutes)}</p>{item.createdAt && <small>Logged {new Intl.DateTimeFormat(undefined, { timeZone, dateStyle: "medium", timeStyle: "short" }).format(new Date(item.createdAt))}</small>}<small>{item.status === "counted" ? "Counted" : "Deleted"} - {outreachEntrySource(item.attribution)}{item.staffReason ? ` - Staff reason: ${item.staffReason}` : ""}{item.taskNotes ? ` - ${item.taskNotes}` : ""}</small></div></article>)}
    {!loading && !error && !page?.items.length && <p>No participation submissions yet.</p>}
    <nav ref={pagination} className="outreach-submission-pagination" aria-label="Submission log pages"><button className="ui-button" type="button" disabled={loading || !previous.length} onClick={() => { setCursor(previous[previous.length - 1] ?? null); setPrevious(previous.slice(0, -1)); }}>Previous submissions</button><span aria-live="polite">Page {previous.length + 1}</span><button className="ui-button" type="button" disabled={loading || !page?.nextCursor} onClick={() => { setPrevious([...previous, cursor]); setCursor(page!.nextCursor); }}>Next submissions</button></nav>
  </section>;
}

function CorrectionCard({ item, activities, members, context, onChanged, setNotice }: { item: Correction; activities: Activity[]; members: Member[]; context: EntryContext; onChanged: () => Promise<void>; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [selectedEntry, setSelectedEntry] = useState<Entry>();
  const entryId = selectedEntry?.id ?? item.entryId; const entryRevision = selectedEntry?.revision ?? item.entryRevision;
  const canRevise = Boolean(entryId && (selectedEntry?.status ?? item.entryStatus) === "counted" && entryRevision !== null);
  const [action, setAction] = useState<"acknowledged" | "dismissed" | "corrected" | "voided">(canRevise ? "corrected" : "acknowledged"); const [note, setNote] = useState(""); const [memberId, setMemberId] = useState(item.entryMemberId ?? ""); const [activityId, setActivityId] = useState(item.activityId ?? item.entryActivityId ?? ""); const [startLocal, setStartLocal] = useState(item.startLocal ?? "09:00"); const [endLocal, setEndLocal] = useState(item.endLocal ?? "10:00"); const [startOccurrence, setStartOccurrence] = useState<CivilTimeOccurrence | undefined>(item.startOccurrence ?? undefined); const [endOccurrence, setEndOccurrence] = useState<CivilTimeOccurrence | undefined>(item.endOccurrence ?? undefined); const [taskNotes, setTaskNotes] = useState(item.taskNotes ?? ""); const [saving, setSaving] = useState(false); const activity = activities.find((candidate) => candidate.id === activityId);
  const correctionDate = activityId === (selectedEntry?.activityId ?? item.entryActivityId) ? selectedEntry?.serviceDate ?? item.entryServiceDate ?? activity?.serviceDate ?? "" : activity?.serviceDate ?? "";
  function chooseEntry(entry?: Entry) { setSelectedEntry(entry); setAction(entry?.status === "counted" ? "corrected" : "acknowledged"); setMemberId(entry?.memberId ?? ""); setActivityId(entry?.activityId ?? item.activityId ?? ""); setStartLocal(entry?.startLocal ?? "09:00"); setEndLocal(entry?.endLocal ?? "10:00"); setStartOccurrence(entry?.startOccurrence ?? undefined); setEndOccurrence(entry?.endOccurrence ?? undefined); setTaskNotes(entry?.taskNotes ?? ""); }
  async function resolve(event: React.FormEvent) {
    event.preventDefault(); const body: Record<string, unknown> = { action, note, requestRevision: item.revision };
    if (action === "voided") Object.assign(body, { entryRevision, ...(selectedEntry ? { entryId } : {}) });
    if (action === "corrected") Object.assign(body, { entryRevision, ...(selectedEntry ? { entryId } : {}), memberId, activityId, startLocal, endLocal, ...(startOccurrence ? { startOccurrence } : {}), ...(endOccurrence ? { endOccurrence } : {}), taskNotes });
    setSaving(true); try { await api(`/admin/hours/corrections/${encodeURIComponent(item.id)}/resolve`, { method: "POST", body: JSON.stringify(body) }); await onChanged(); setNotice({ tone: "success", text: action === "corrected" ? "Correction applied as one immutable entry revision." : action === "voided" ? "Entry voided through the correction workflow." : "Correction request resolved without changing participation totals." }); } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setSaving(false); }
  }
  return <form className="ui-card ui-form outreach-stack" onSubmit={resolve}>
    <div><strong>{item.memberName} ({item.externalId})</strong><p>{item.channel === "discord" ? "Linked Discord request" : "Public form request"} - {item.activityTitle ?? item.claimedServiceDate ?? "Activity unavailable"}</p><blockquote>{item.message}</blockquote></div>
    {!item.entryId && item.activityId && <CorrectionEntryPicker requestId={item.id} selectedId={selectedEntry?.id ?? ""} onChange={chooseEntry} disabled={saving} />}
    <label>Decision<select className="ui-native-select" value={action} onChange={(event) => setAction(event.target.value as typeof action)}><option value="acknowledged">Approve without changes</option><option value="dismissed">Reject request</option>{canRevise && <><option value="corrected">Approve and correct entry</option><option value="voided">Approve and void entry</option></>}</select></label>
    {action === "corrected" && <><label>Member<select className="ui-native-select" required value={memberId} disabled={Boolean(selectedEntry)} onChange={(event) => setMemberId(event.target.value)}>{members.map((member) => <option key={member.id} value={member.id}>{member.label} ({member.externalId})</option>)}</select></label><label>Dated activity<select className="ui-native-select" required value={activityId} disabled={Boolean(selectedEntry)} onChange={(event) => { setActivityId(event.target.value); setStartOccurrence(undefined); setEndOccurrence(undefined); }}>{activities.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.serviceDate} - {candidate.title}</option>)}</select></label><div className="outreach-time-grid"><OutreachClock label="Corrected start time" date={correctionDate} time={startLocal} zone={selectedEntry?.timeZone ?? context.timeZone} occurrence={startOccurrence} onTime={setStartLocal} onOccurrence={setStartOccurrence} disabled={saving || !activity} /><OutreachClock label="Corrected end time" date={correctionDate} time={endLocal} zone={selectedEntry?.timeZone ?? context.timeZone} occurrence={endOccurrence} onTime={setEndLocal} onOccurrence={setEndOccurrence} disabled={saving || !activity} /></div><label>Corrected task notes<textarea maxLength={4000} value={taskNotes} onChange={(event) => setTaskNotes(event.target.value)} /></label></>}
    <label>Staff review note<textarea required maxLength={4000} value={note} onChange={(event) => setNote(event.target.value)} /></label><button className="ui-button ui-button--primary" disabled={saving || !note.trim() || action === "corrected" && (!canRevise || !memberId || !activityId)}>Resolve correction</button>
  </form>;
}

function CorrectionEntryPicker({ requestId, selectedId, onChange, disabled }: { requestId: string; selectedId: string; onChange: (entry?: Entry) => void; disabled: boolean }) {
  const [entries, setEntries] = useState<Entry[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  useEffect(() => {
    const controller = new AbortController();
    void loadOutreachPages<Entry>(`/admin/hours/corrections/${encodeURIComponent(requestId)}/entries?limit=100`, controller.signal).then((items) => { if (!controller.signal.aborted) setEntries(items); }).catch((caught) => { if (!controller.signal.aborted) setError((caught as Error).message); }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [requestId]);
  return <div className="outreach-stack"><label>Participation entry to correct<select className="ui-native-select" disabled={disabled || loading || Boolean(error)} value={selectedId} onChange={(event) => onChange(entries.find((entry) => entry.id === event.target.value))}><option value="">Choose the affected submission</option>{entries.map((entry) => <option key={entry.id} value={entry.id}>{entry.serviceDate} - {entry.startLocal} to {entry.endLocal} - {(entry.durationMinutes / 60).toFixed(2)} hours - {entry.status}</option>)}</select></label>{loading ? <p className="ui-status" role="status">Loading this member's submissions for this activity...</p> : error ? <p className="ui-status" data-tone="error" role="alert">{error}</p> : !entries.length ? <p>No matching submissions. You can acknowledge or reject this request without changing recorded hours.</p> : <p className="field-help">Select the submission described in the request. Other members' submissions are not included.</p>}</div>;
}
